"use client";

import { useState, useRef, useEffect } from "react";

type ClickRow   = { name: string; cur: string; prev: string; feb: string; jan: string; dec: string };
type PosRow     = { name: string; cur: string | number; feb: string | number; jan: string | number; dec: string | number };
type Report     = {
  curLabel:  string;
  prevLabel: string;
  clicks:   { rows: ClickRow[]; total: ClickRow };
  position: PosRow[];
  content:  { mar: number; feb: number; jan: number; dec: number };
};
type Message = { role: "user" | "assistant"; text: string; report?: Report };

function ReportTable({ report }: {
  report: Report;
}) {
  return (
    <div className="mt-2 flex flex-col gap-4 text-xs font-mono">

      {/* Clicks */}
      <div>
        <p className="mb-1 font-sans font-semibold text-zinc-700 dark:text-zinc-300">📊 Organic Traffic (Clicks)</p>
        <div className="overflow-x-auto rounded-lg border border-zinc-200 dark:border-zinc-700">
          <table className="w-full text-left">
            <thead className="bg-zinc-100 dark:bg-zinc-800 text-zinc-500 dark:text-zinc-400">
              <tr>
                <th className="px-3 py-2">Project</th>
                <th className="px-3 py-2 text-right">{report.curLabel}</th>
                <th className="px-3 py-2 text-right">{report.prevLabel}</th>
                <th className="px-3 py-2 text-right">Feb</th>
                <th className="px-3 py-2 text-right">Jan</th>
                <th className="px-3 py-2 text-right">Dec</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-zinc-100 dark:divide-zinc-800">
              {report.clicks.rows.map((r) => (
                <tr key={r.name} className="bg-white dark:bg-zinc-900">
                  <td className="px-3 py-2 text-zinc-800 dark:text-zinc-200">{r.name}</td>
                  <td className="px-3 py-2 text-right text-zinc-700 dark:text-zinc-300">{r.cur}</td>
                  <td className="px-3 py-2 text-right text-zinc-700 dark:text-zinc-300">{r.prev}</td>
                  <td className="px-3 py-2 text-right text-zinc-700 dark:text-zinc-300">{r.feb}</td>
                  <td className="px-3 py-2 text-right text-zinc-700 dark:text-zinc-300">{r.jan}</td>
                  <td className="px-3 py-2 text-right text-zinc-700 dark:text-zinc-300">{r.dec}</td>
                </tr>
              ))}
              <tr className="bg-zinc-50 dark:bg-zinc-800 font-semibold">
                <td className="px-3 py-2 text-zinc-900 dark:text-zinc-100">Total</td>
                <td className="px-3 py-2 text-right text-zinc-900 dark:text-zinc-100">{report.clicks.total.cur}</td>
                <td className="px-3 py-2 text-right text-zinc-900 dark:text-zinc-100">{report.clicks.total.prev}</td>
                <td className="px-3 py-2 text-right text-zinc-900 dark:text-zinc-100">{report.clicks.total.feb}</td>
                <td className="px-3 py-2 text-right text-zinc-900 dark:text-zinc-100">{report.clicks.total.jan}</td>
                <td className="px-3 py-2 text-right text-zinc-900 dark:text-zinc-100">{report.clicks.total.dec}</td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>

      {/* Position */}
      <div>
        <p className="mb-1 font-sans font-semibold text-zinc-700 dark:text-zinc-300">📍 Avg Organic Position</p>
        <div className="overflow-x-auto rounded-lg border border-zinc-200 dark:border-zinc-700">
          <table className="w-full text-left">
            <thead className="bg-zinc-100 dark:bg-zinc-800 text-zinc-500 dark:text-zinc-400">
              <tr>
                <th className="px-3 py-2">Project</th>
                <th className="px-3 py-2 text-right">{report.curLabel}</th>
                <th className="px-3 py-2 text-right">Feb</th>
                <th className="px-3 py-2 text-right">Jan</th>
                <th className="px-3 py-2 text-right">Dec</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-zinc-100 dark:divide-zinc-800">
              {report.position.map((r) => (
                <tr key={r.name} className="bg-white dark:bg-zinc-900">
                  <td className="px-3 py-2 text-zinc-800 dark:text-zinc-200">{r.name}</td>
                  <td className="px-3 py-2 text-right text-zinc-700 dark:text-zinc-300">{r.cur}</td>
                  <td className="px-3 py-2 text-right text-zinc-700 dark:text-zinc-300">{r.feb}</td>
                  <td className="px-3 py-2 text-right text-zinc-700 dark:text-zinc-300">{r.jan}</td>
                  <td className="px-3 py-2 text-right text-zinc-700 dark:text-zinc-300">{r.dec}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Content */}
      <div>
        <p className="mb-1 font-sans font-semibold text-zinc-700 dark:text-zinc-300">✍️ Content Pieces Shipped</p>
        <div className="overflow-x-auto rounded-lg border border-zinc-200 dark:border-zinc-700">
          <table className="w-full text-left">
            <thead className="bg-zinc-100 dark:bg-zinc-800 text-zinc-500 dark:text-zinc-400">
              <tr>
                <th className="px-3 py-2"></th>
                <th className="px-3 py-2 text-right">Mar</th>
                <th className="px-3 py-2 text-right">Feb</th>
                <th className="px-3 py-2 text-right">Jan</th>
                <th className="px-3 py-2 text-right">Dec</th>
              </tr>
            </thead>
            <tbody>
              <tr className="bg-white dark:bg-zinc-900">
                <td className="px-3 py-2 text-zinc-800 dark:text-zinc-200">Content Pieces Shipped</td>
                <td className="px-3 py-2 text-right text-zinc-700 dark:text-zinc-300">{report.content.mar}</td>
                <td className="px-3 py-2 text-right text-zinc-700 dark:text-zinc-300">{report.content.feb}</td>
                <td className="px-3 py-2 text-right text-zinc-700 dark:text-zinc-300">{report.content.jan}</td>
                <td className="px-3 py-2 text-right text-zinc-700 dark:text-zinc-300">{report.content.dec}</td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>

    </div>
  );
}

export default function Home() {
  const [messages, setMessages] = useState<Message[]>([
    { role: "assistant", text: 'Hi! Type "send report" to preview the organic traffic report.' },
  ]);
  const [input, setInput]   = useState("");
  const [loading, setLoading]   = useState(false);
  const [step, setStep]         = useState("idle");
const bottomRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages, loading]);

  async function handleSend() {
    const text = input.trim();
    if (!text || loading) return;

    const newMessages: Message[] = [...messages, { role: "user", text }];
    setMessages(newMessages);
    setInput("");
    setLoading(true);

    try {
      const res  = await fetch("/api/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ message: text, step }),
      });
      const data = await res.json();
      setMessages([...newMessages, { role: "assistant", text: data.reply, report: data.report }]);
      setStep(data.nextStep ?? "idle");
    } catch {
      setMessages([...newMessages, { role: "assistant", text: "Something went wrong. Please try again." }]);
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="flex min-h-screen items-center justify-center bg-zinc-100 font-sans dark:bg-zinc-950">
      <main className="flex w-full max-w-3xl flex-col h-[90vh] bg-white dark:bg-zinc-900 rounded-2xl shadow-xl overflow-hidden border border-zinc-200 dark:border-zinc-800">

        {/* Header */}
        <div className="flex items-center gap-3 px-6 py-4 border-b border-zinc-100 dark:border-zinc-800">
          <div className="w-2.5 h-2.5 rounded-full bg-green-500" />
          <div>
            <h1 className="text-sm font-semibold text-zinc-900 dark:text-zinc-100">SEO Report Assistant</h1>
            <p className="text-xs text-zinc-400">New Auto – Organic Traffic · #aakash-ai-experiment</p>
          </div>
        </div>

        {/* Messages */}
        <div className="flex-1 overflow-y-auto px-6 py-4 flex flex-col gap-4">
          {messages.map((msg, i) => (
            <div key={i} className={`flex ${msg.role === "user" ? "justify-end" : "justify-start"}`}>
              <div className={`max-w-full rounded-2xl px-4 py-2.5 text-sm leading-relaxed ${
                msg.role === "user"
                  ? "bg-zinc-900 text-white dark:bg-white dark:text-black rounded-br-sm max-w-[70%]"
                  : "bg-zinc-100 text-zinc-800 dark:bg-zinc-800 dark:text-zinc-100 rounded-bl-sm w-full"
              }`}>
                {msg.text}
                {msg.report && (
                  <ReportTable report={msg.report} />
                )}
              </div>
            </div>
          ))}
          {loading && (
            <div className="flex justify-start">
              <div className="bg-zinc-100 dark:bg-zinc-800 rounded-2xl rounded-bl-sm px-4 py-2.5 flex gap-1 items-center">
                <span className="w-1.5 h-1.5 rounded-full bg-zinc-400 animate-bounce [animation-delay:0ms]" />
                <span className="w-1.5 h-1.5 rounded-full bg-zinc-400 animate-bounce [animation-delay:150ms]" />
                <span className="w-1.5 h-1.5 rounded-full bg-zinc-400 animate-bounce [animation-delay:300ms]" />
              </div>
            </div>
          )}
          <div ref={bottomRef} />
        </div>

        {/* Input */}
        <div className="px-4 py-4 border-t border-zinc-100 dark:border-zinc-800 flex gap-2">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && handleSend()}
            placeholder={step === "awaiting_count" ? "Enter content pieces count..." : "Type a message..."}
            className="flex-1 rounded-full border border-zinc-200 dark:border-zinc-700 bg-zinc-50 dark:bg-zinc-800 px-4 py-2.5 text-sm outline-none focus:border-zinc-400 dark:text-zinc-100 placeholder:text-zinc-400"
          />
          <button
            onClick={handleSend}
            disabled={loading || !input.trim()}
            className="rounded-full bg-zinc-900 dark:bg-white px-5 py-2.5 text-sm font-medium text-white dark:text-black hover:bg-zinc-700 dark:hover:bg-zinc-200 disabled:opacity-40 transition-colors"
          >
            Send
          </button>
        </div>
      </main>
    </div>
  );
}

