import { NextRequest, NextResponse } from "next/server";

const SLACK_WEBHOOK_URL = process.env.SLACK_WEBHOOK_URL ?? "";

function fmt(n: string | number) { return String(n); }

export async function POST(req: NextRequest) {
  if (!SLACK_WEBHOOK_URL) {
    return NextResponse.json({ ok: false, error: "SLACK_WEBHOOK_URL not set in .env.local" });
  }

  const { report } = await req.json();
  const { curLabel, prevLabel, clicks, position, content } = report;

  const clicksRows = clicks.rows
    .map((r: { name: string; cur: string; prev: string; feb: string; jan: string; dec: string }) =>
      `${r.name.padEnd(22)}| ${fmt(r.cur).padStart(10)} | ${fmt(r.prev).padStart(10)} | ${fmt(r.feb).padStart(9)} | ${fmt(r.jan).padStart(9)} | ${fmt(r.dec).padStart(9)}`
    ).join("\n");

  const posRows = position
    .map((r: { name: string; cur: string | number; feb: string | number; jan: string | number; dec: string | number }) =>
      `${r.name.padEnd(22)}| ${fmt(r.cur).padStart(8)} | ${fmt(r.feb).padStart(8)} | ${fmt(r.jan).padStart(8)} | ${fmt(r.dec).padStart(8)}`
    ).join("\n");

  const body = {
    text: "New Auto – Organic Traffic Update",
    blocks: [
      {
        type: "header",
        text: { type: "plain_text", text: "🚗 New Auto – Organic Traffic Update", emoji: true },
      },
      { type: "divider" },
      {
        type: "section",
        text: {
          type: "mrkdwn",
          text:
            `*📊 Organic Traffic (Clicks)*\n\`\`\`\n` +
            `${"Project".padEnd(22)}| ${curLabel.padStart(10)} | ${prevLabel.padStart(10)} | ${"Feb".padStart(9)} | ${"Jan".padStart(9)} | ${"Dec".padStart(9)}\n` +
            `${"─".repeat(78)}\n` +
            clicksRows + "\n" +
            `${"─".repeat(78)}\n` +
            `${"Total".padEnd(22)}| ${fmt(clicks.total.cur).padStart(10)} | ${fmt(clicks.total.prev).padStart(10)} | ${fmt(clicks.total.feb).padStart(9)} | ${fmt(clicks.total.jan).padStart(9)} | ${fmt(clicks.total.dec).padStart(9)}\n\`\`\``,
        },
      },
      { type: "divider" },
      {
        type: "section",
        text: {
          type: "mrkdwn",
          text:
            `*📍 Avg Organic Position*\n\`\`\`\n` +
            `${"Project".padEnd(22)}| ${curLabel.padStart(8)} | ${"Feb".padStart(8)} | ${"Jan".padStart(8)} | ${"Dec".padStart(8)}\n` +
            `${"─".repeat(58)}\n` +
            posRows + "\n\`\`\`",
        },
      },
      { type: "divider" },
      {
        type: "section",
        text: {
          type: "mrkdwn",
          text:
            `*✍️ Content Pieces Shipped*\n\`\`\`\n` +
            `${"".padEnd(22)}| ${"Mar".padStart(6)} | ${"Feb".padStart(6)} | ${"Jan".padStart(6)} | ${"Dec".padStart(6)}\n` +
            `${"─".repeat(50)}\n` +
            `${"Content Pieces Shipped".padEnd(22)}| ${String(content.mar).padStart(6)} | ${String(content.feb).padStart(6)} | ${String(content.jan).padStart(6)} | ${String(content.dec).padStart(6)}\n\`\`\``,
        },
      },
    ],
  };

  const res = await fetch(SLACK_WEBHOOK_URL, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });

  if (!res.ok) {
    return NextResponse.json({ ok: false, error: `Slack responded with ${res.status}` });
  }

  return NextResponse.json({ ok: true });
}

